// Compute previous month range
const now = new Date();
const start = new Date(now.getFullYear(), now.getMonth() - 1, 1);
const end = new Date(now.getFullYear(), now.getMonth(), 0);
const pad = (n) => String(n).padStart(2, '0');
const startStr = `${start.getFullYear()}-${pad(start.getMonth() + 1)}-01`;
const endStr = `${end.getFullYear()}-${pad(end.getMonth() + 1)}-${pad(end.getDate())}`;
const label = start.toLocaleDateString('fr-FR', { month: 'long', year: 'numeric' });
return [{ json: { ...$json, _start: startStr, _end: endStr, _label: label } }];

const ctx = $('Compute period').item.json;
const rows = $json || [];
let ca = 0, charges = 0, tvaC = 0, tvaD = 0, anomalies = 0;
const byAccount = {};
for (const t of rows) {
  const amt = Number(t.amount) || 0;
  const tva = Number(t.tva_amount) || 0;
  const isCredit = t.type === 'credit' || amt > 0;
  if (isCredit) { ca += Math.abs(amt); tvaC += tva; }
  else {
    charges += Math.abs(amt);
    if (t.tva_deductible) tvaD += tva;
    const key = t.pcg_label || t.pcg_account || 'autres';
    byAccount[key] = (byAccount[key] || 0) + Math.abs(amt);
  }
  if (t.is_anomaly) anomalies++;
}
const topCharges = Object.entries(byAccount).sort((a, b) => b[1] - a[1]).slice(0, 5);
return [{ json: { ...ctx, _summary: {
  tx_count: rows.length, ca: Math.round(ca * 100) / 100, charges: Math.round(charges * 100) / 100,
  resultat: Math.round((ca - charges) * 100) / 100,
  tva_collectee: Math.round(tvaC * 100) / 100, tva_deductible: Math.round(tvaD * 100) / 100,
  tva_nette: Math.round((tvaC - tvaD) * 100) / 100,
  anomalies, top_charges: topCharges,
} } }];

