const ctx = $('Aggregate').item.json;
const narrative = $json.content?.[0]?.text || '';
const s = ctx._summary;
const body = `${ctx._label} · CA ${s.ca}€ · Charges ${s.charges}€ · Résultat ${s.resultat}€${s.anomalies ? ' · ' + s.anomalies + ' anomalie(s)' : ''}`;
return [{ json: {
  user_id: ctx.user_id,
  agent_type: 'compta',
  title: `📊 Rapport mensuel — ${ctx._label}`,
  body,
  action_type: 'review',
  action_payload: { period: ctx._label, narrative },
  action_url: '/dashboard/compta-agent/reports',
  priority: 'normal',
  channels: ['push', 'in_app'],
} }];
